"""In-place foreach acos (``aten::_foreach_acos_``) for Ascend910B.

Every tensor of the input list is mutated in place: the same storage, the same
strides and the same dtype afterwards, and the call returns ``None``.  The
in-place schema only accepts floating dtypes, because ATen refuses to narrow a
promoted ``Float`` result back into an integral tensor.

Two structural choices carry the performance:

* **Math.** ``acos`` is evaluated as ``sqrt(1 - |x|) * G(|x|)`` with a degree-4
  ``G`` and a ``pi - r`` reflection, a single branch with no vector divide.  The
  Ascend libdevice ``acos`` alternatively evaluates a degree-10 centre
  polynomial *and* a sqrt+divide+atan branch unconditionally (~40 vector ops per
  tile); this form is ~15 ops with 1.3e-5 fp32 error against a 1e-4 budget.
* **Launch count and tile size.** ``BLOCK`` is 4096 elements so the fixed
  per-program cost is amortised, and all flat-addressable tensors of one dtype
  are processed by a single launch (grid = ``(n_tensors, tiles)``) so a list of
  many small tensors pays one launch instead of one per tensor.

Layout strategy: an element-wise, order-independent op only needs to visit each
logical element once.  For a non-overlapping-and-dense tensor (which includes
any transpose or dim-0 slice) the storage span from ``data_ptr`` holds exactly
``numel`` elements, so a flat linear traversal is correct and needs no index
decomposition.  Only genuinely gappy views fall back to the strided kernel,
where the collapsed dims are decomposed in-kernel.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 4096
_MAX_RANK = 8
_MAX_GROUP = 16

_FLOAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32, torch.float64)

_INT_NAMES = {
    torch.int64: "Long",
    torch.int32: "Int",
    torch.int16: "Short",
    torch.int8: "Char",
    torch.uint8: "Byte",
    torch.bool: "Bool",
}


@triton.jit
def _acos_f32(x):
    """acos on fp32 with one branch instead of the library's two.

    ``acos(a) = sqrt(1 - a) * G(a)`` is analytic on ``a in [0, 1]`` (the square
    root cancels the branch point at 1) and ``G`` is a degree-4 polynomial whose
    fp32 max absolute error is 1.3e-5, well inside the 1e-4 budget.  Using
    ``|x|`` and reflecting with ``pi - r`` removes the library's second branch,
    its vector divide and half of its ~40 vector ops per tile:

    * ``sqrt(1 - |x|)`` is NaN for ``|x| > 1``, so out-of-domain and non-finite
      inputs propagate NaN exactly like ATen;
    * ``|x| == 1`` gives ``0`` (and ``pi`` for ``x == -1``) exactly;
    * ``G(0)`` is pi/2 to within 5.4e-6, so ``acos(+-0)`` keeps its value.
    """
    a = tl.abs(x)
    g = 1.5707909 + a * (
        -0.21425503 + a * (0.08548517 + a * (-0.037332516 + a * 0.00956983))
    )
    r = tl.sqrt(1.0 - a) * g
    return tl.where(x < 0, 3.141592653589793 - r, r)


@triton.jit
def _acos_flat_kernel(x_ptr, n, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    tl.store(x_ptr + offs, _acos_f32(x.to(tl.float32)).to(x.dtype), mask=mask)


@triton.jit
def _acos_multi_kernel(
    x0,
    n0,
    n1,
    n2,
    n3,
    n4,
    n5,
    n6,
    n7,
    n8,
    n9,
    n10,
    n11,
    n12,
    n13,
    n14,
    n15,
    o0,
    o1,
    o2,
    o3,
    o4,
    o5,
    o6,
    o7,
    o8,
    o9,
    o10,
    o11,
    o12,
    o13,
    o14,
    o15,
    BLOCK: tl.constexpr,
):
    """One launch for up to 16 same-dtype tensors.

    ``x0`` fixes the pointer element type; every other tensor of the group is
    reached as ``x0 + oi`` where ``oi`` is its element offset from ``x0``
    (computed on the host from ``data_ptr``), so the group needs no per-tensor
    pointer arguments and no host-to-device metadata copy.  Grid axis 0 picks
    the tensor, axis 1 the tile inside it.  Unused slots carry ``n = 0`` and are
    never reached because axis 0 has extent ``len(group)``.
    """
    t = tl.program_id(0)
    off = tl.program_id(1) * BLOCK
    n = n0
    d = o0.to(tl.int64)
    if t == 1:
        n = n1
        d = o1.to(tl.int64)
    if t == 2:
        n = n2
        d = o2.to(tl.int64)
    if t == 3:
        n = n3
        d = o3.to(tl.int64)
    if t == 4:
        n = n4
        d = o4.to(tl.int64)
    if t == 5:
        n = n5
        d = o5.to(tl.int64)
    if t == 6:
        n = n6
        d = o6.to(tl.int64)
    if t == 7:
        n = n7
        d = o7.to(tl.int64)
    if t == 8:
        n = n8
        d = o8.to(tl.int64)
    if t == 9:
        n = n9
        d = o9.to(tl.int64)
    if t == 10:
        n = n10
        d = o10.to(tl.int64)
    if t == 11:
        n = n11
        d = o11.to(tl.int64)
    if t == 12:
        n = n12
        d = o12.to(tl.int64)
    if t == 13:
        n = n13
        d = o13.to(tl.int64)
    if t == 14:
        n = n14
        d = o14.to(tl.int64)
    if t == 15:
        n = n15
        d = o15.to(tl.int64)
    base = x0 + d
    idx = off + tl.arange(0, BLOCK)
    mask = idx < n
    x = tl.load(base + idx, mask=mask, other=0.0)
    tl.store(base + idx, _acos_f32(x.to(tl.float32)).to(x.dtype), mask=mask)


@triton.jit
def _acos_strided_kernel(
    x_ptr,
    n,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    t6,
    t7,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = (pid * BLOCK + tl.arange(0, BLOCK)).to(tl.int64)
    mask = offs < n
    rem = offs
    addr = tl.zeros([BLOCK], dtype=tl.int64)
    if RANK >= 1:
        q = rem % s0
        rem = rem // s0
        addr += q * t0
    if RANK >= 2:
        q = rem % s1
        rem = rem // s1
        addr += q * t1
    if RANK >= 3:
        q = rem % s2
        rem = rem // s2
        addr += q * t2
    if RANK >= 4:
        q = rem % s3
        rem = rem // s3
        addr += q * t3
    if RANK >= 5:
        q = rem % s4
        rem = rem // s4
        addr += q * t4
    if RANK >= 6:
        q = rem % s5
        rem = rem // s5
        addr += q * t5
    if RANK >= 7:
        q = rem % s6
        rem = rem // s6
        addr += q * t6
    if RANK >= 8:
        q = rem % s7
        rem = rem // s7
        addr += q * t7
    x = tl.load(x_ptr + addr, mask=mask, other=0.0)
    tl.store(x_ptr + addr, _acos_f32(x.to(tl.float32)).to(x.dtype), mask=mask)


def _flat_addressable(t):
    """Whether ``[data_ptr, data_ptr + numel)`` covers exactly this tensor.

    Equivalent to ``is_non_overlapping_and_dense``, which torch_npu does not
    expose.  A transposed but dense tensor qualifies: its elements are visited
    in memory order, and an in-place elementwise op is order independent, so a
    flat traversal still touches every logical element exactly once.
    """
    if t.is_contiguous():
        return True
    if t.numel() <= 1:
        return True
    expected = 1
    for stride, size in sorted(
        (s, sz) for s, sz in zip(t.stride(), t.shape) if sz != 1
    ):
        if stride != expected:
            return False
        expected *= size
    return True


def _collapse_dims(t):
    """Collapse adjacent dims that describe one contiguous run.

    Pure integer metadata arithmetic: the resulting (shape, stride) pair maps
    the same logical elements to the same addresses, just with fewer terms.
    """
    shape = []
    strides = []
    for s, st in zip(t.shape, t.stride()):
        s = int(s)
        st = int(st)
        if s == 1:
            continue
        if shape and strides[-1] == st * s:
            shape[-1] *= s
            strides[-1] = st
        else:
            shape.append(s)
            strides.append(st)
    return shape, strides


def _launch_flat(t, n):
    grid = (triton.cdiv(n, _BLOCK),)
    _acos_flat_kernel[grid](t, n, BLOCK=_BLOCK)


def _launch_multi(items):
    """One launch for a whole same-dtype group of flat-addressable tensors."""
    t0 = items[0][0]
    itemsz = t0.element_size()
    base = t0.data_ptr()
    counts = [0] * _MAX_GROUP
    deltas = [0] * _MAX_GROUP
    max_n = 0
    for i, (t, n) in enumerate(items):
        counts[i] = n
        deltas[i] = (t.data_ptr() - base) // itemsz
        if n > max_n:
            max_n = n
    grid = (len(items), triton.cdiv(max_n, _BLOCK))
    _acos_multi_kernel[grid](t0, *counts, *deltas, BLOCK=_BLOCK)


def _launch_strided(t, n):
    shape, strides = _collapse_dims(t)
    rank = len(shape)
    if rank > _MAX_RANK:
        raise NotImplementedError(
            "foreach_acos_ supports at most %d collapsed dims on a gappy view"
            % _MAX_RANK
        )
    pad = _MAX_RANK - rank
    shape = shape + [1] * pad
    strides = strides + [0] * pad
    grid = (triton.cdiv(n, _BLOCK),)
    _acos_strided_kernel[grid](t, n, *shape, *strides, RANK=rank, BLOCK=_BLOCK)


def foreach_acos_(self):
    """In-place acos over a TensorList; returns ``None`` like ATen."""
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    tensors = list(self)
    if not tensors:
        raise RuntimeError("Tensor list must have at least one tensor.")

    plans = []
    for t in tensors:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        dt = t.dtype
        if dt not in _FLOAT_DTYPES:
            if dt in _INT_NAMES:
                raise RuntimeError(
                    "result type Float can't be cast to the desired output type "
                    + _INT_NAMES[dt]
                )
            raise NotImplementedError(
                "\"foreach\" not implemented for '%s'" % str(dt).replace("torch.", "")
            )
        n = t.numel()
        if n == 0:
            continue
        if _flat_addressable(t):
            plans.append((t, n, True))
        else:
            if torch._debug_has_internal_overlap(t) == 1:
                raise RuntimeError(
                    "unsupported operation: more than one element of the written-to "
                    "tensor refers to a single memory location. Please clone() the "
                    "tensor before performing the operation."
                )
            plans.append((t, n, False))

    # Aliased entries must keep their sequential semantics, so a list whose
    # entries share a base address is executed strictly per tensor.
    ptrs = [t.data_ptr() for t, _, _ in plans]
    fuse = len(set(ptrs)) == len(ptrs)

    groups = {}
    order = []
    solo = []
    for t, n, flat in plans:
        if not flat or not fuse:
            solo.append((t, n, flat))
            continue
        key = t.dtype
        bucket = groups.get(key)
        if bucket is None:
            bucket = groups[key] = []
            order.append(key)
        bucket.append((t, n))

    for key in order:
        items = groups[key]
        if len(items) == 1:
            _launch_flat(items[0][0], items[0][1])
        else:
            for start in range(0, len(items), _MAX_GROUP):
                chunk = items[start : start + _MAX_GROUP]
                if len(chunk) == 1:
                    _launch_flat(chunk[0][0], chunk[0][1])
                else:
                    _launch_multi(chunk)

    for t, n, flat in solo:
        if flat:
            _launch_flat(t, n)
        else:
            _launch_strided(t, n)
    return None
